import { Component, inject } from "@angular/core";
import { BaseClassNG } from "./base.class.a.ng";
import { HTTP_UOW } from "@_core/_client";
import { FormService, ValidatorService } from "@_core/_form";
import { LocalStorageService, StateService } from "@_core/store";
import { UtilService } from "@_core/service";
import { TemplateService } from "@_core/_template";
import { DialogCommonService, NotifyService } from "@_core/components";
import { SideNavService } from "@_theme/full-template/side-nav.service";

@Component({ template: '' })
export abstract class BaseClassSrvc extends BaseClassNG {
  public _httpUwo = inject(HTTP_UOW);
  public _fs = inject(FormService);
  public _vs = inject(ValidatorService);
  public _ss = inject(StateService);
  public _storage = inject(LocalStorageService);
  public _util = inject(UtilService);

  public _template = inject(TemplateService);
  public _sideNav = inject(SideNavService)
  public _dialog = inject(DialogCommonService);
  public _notify = inject(NotifyService);
}
