import { Injectable, Type } from '@angular/core'
import { MatSidenav } from '@angular/material/sidenav'
import { BehaviorSubject } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class SideNavService {
  public Left: Partial<MatSidenav> = {
    mode: 'push',
    position: 'start',
    opened: true,
    disableClose: true
  }
  public Right: Partial<MatSidenav> = {
    mode: 'push',
    position: 'end',
    opened: false,
    disableClose: true
  }

  private componentRight = new BehaviorSubject<Type<any> | null>(null);

  componentRight$ = this.componentRight.asObservable();

  showRight(component: Type<any>) {
    this.componentRight.next(component);
  }

  clearRight() {
    this.componentRight.next(null);
  }
  constructor() { }
}
export interface SidebarPanel {
  id: string;
  title: string;
  icon: string;
  order: number;
  closable: boolean;
}
